#!/bin/sh
# The status.sh --json of a plan, with only the tasks that call for action: the
# in-progress ones, the ones that can start now (available, then owner, each
# group from the one that unblocks the most to the one that unblocks the least)
# and the invalid ones. The rest of the object (contract, name, progress, phases,
# parallel, run) comes out as status.sh gives it, with the same keys.
# Usage: sh summary.sh <plan-dir>
# So the run skill's conductor can read the status through --json without a pipe
# on the command line and without paying for the done, cancelled, draft and
# blocked tasks of a large plan on every cycle. Needs jq (check.sh makes it
# mandatory).
# Errors come out in the package language.

language='pt-BR'
# >>> strings (area summary.): generated by tools/script-strings.sh from core/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='summary.usage	x-test:summary.usage
summary.noJq	x-test:summary.noJq
' ;;
  pt-BR) MSG_TABLE='summary.usage	Uso: sh summary.sh <plan-dir> (pasta com status.sh)
summary.noJq	summary.sh precisa de jq
' ;;
  *) MSG_TABLE='summary.usage	Usage: sh summary.sh <plan-dir> (a folder with status.sh)
summary.noJq	summary.sh needs jq
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings

[ -f "$1/status.sh" ] || { msg summary.usage >&2; exit 1; }
command -v jq >/dev/null 2>&1 || { msg summary.noJq >&2; exit 1; }

sh "$1/status.sh" --json | jq '
  def rank: {"in-progress": 0, "available": 1, "owner": 2, "invalid": 3}[.group];
  .tasks |= (map(select(rank != null)) | sort_by(rank, -.unblocks))
'
